//Numerical Types: byte, short, int, long, sbyte, ushort, uint, ulong, char
byte aSingleByte = 200;
short shortInteger = 30000;
int integer = 2147483640;
long longInteger = 9223372036854775807L;
sbyte aSingleSignedByte = -126;
ushort unsignedShortInteger = 65534;
uint unsignedInteger = 4294967295U;
ulong unsignedLonInteger = 18446744073709551615UL;
char aSingleCharacter = 'c';

//Floating Point Types: float, double
float singlePrecisionFloatingPoint = 3.;
double doublePrecisionFloatingPoint = 3.141592653589793238462643383279502884197169399375105820974944592307816406286208998628034825;

//Decimal Type: decimal
decimal decimalNumber = 3.;

//Boolean Type: bool
bool booleanValue = true;

//String Type: string
string stringValue = "Hello, World!";

Console.WriteLine(aSingleByte);
Console.WriteLine(shortInteger);
Console.WriteLine(integer);
Console.WriteLine(longInteger);
Console.WriteLine(aSingleSignedByte);
Console.WriteLine(unsignedShortInteger);
Console.WriteLine(unsignedInteger);
Console.WriteLine(unsignedLonInteger);
Console.WriteLine(aSingleCharacter);
Console.WriteLine(singlePrecisionFloatingPoint);
Console.WriteLine(doublePrecisionFloatingPoint);
Console.WriteLine(decimalNumber);
Console.WriteLine(booleanValue);
Console.WriteLine(stringValue);